const SIG_META = { double: { file: 'searchlight-double', heads: { upper: { h: 21 }, lower: { h: 15 } } }, single: { file: 'searchlight-single', heads: { upper: { h: 21 } } } };
const SIG_VIEW = { front: { suf: '-halfvisor', lamp: a => 'lamp-' + a, x: 4.5 }, front0: { suf: '', lamp: a => 'lamp-' + a, x: 4.5 }, rear: { suf: '-rear', lamp: null }, right: { suf: '-side', lamp: a => 'lamp-side-' + a, x: 5.08 }, left: { suf: '-side-left', lamp: a => 'lamp-side-' + a + '-left', x: 3.92 } };
const LAMP = { red: '#ff3b2f', yellow: '#ffc52e', green: '#3df07a', dark: '#2a2a2a' };
