function efArt(names) { for (const n of names) { if (BA(n)) return n; } return null; }
function drawEFSprite(names, x, y, wFt, hFt) {
  // City callers pass intended CENTRE x; drawSide is left-anchored — subtract half width here.
  // Do not change global drawSide (rail/legacy left-anchor callers depend on it).
  const k = efArt(names); if (!k) return false;
  const w = wFt || 40, h = hFt || 20;
  try { return drawSide(BA(k), x - w / 2, y, w, h); } catch (e) { return false; }
}
