function drawEFNSTile(art, xCentre, y0, y1, tileW, tileD) {
  // Native N–S ground piece: sizeFt [width, depth]; place top-left so centreline sits on xCentre.
  for (let y = y0; y < y1; y += tileD) {
    const d = Math.min(tileD, y1 - y);
    drawEFGround([art], xCentre - tileW / 2, y, tileW, d);
  }
}
