    { const z = EF_SITE['effingham-courthouse']; if (z) drawEFSprite((EF_ART_ALIAS[z.b] || []).concat([z.b + '@2x', z.b]), 2600, courtY, z.sw || 102, z.sh || 82); }
    { const z = EF_SITE['effingham-church']; if (z) drawEFSprite((EF_ART_ALIAS[z.b] || []).concat([z.b + '@2x', z.b]), chCx, churchY, Math.min(z.sw || 64, chPadW - 6), z.sh || 88); }
    drawEFParkedCar(2600 - 50, padBot - 20, 2);
    drawEFParkedCar(2600 + 40, padBot - 18, 5);
