// Bounding boxes of civic pads — housing must skip these (Danny #5)
function efCivicRects() {
  const out = [];
  const places = [
    ['effingham-church', -700, -520],
    ['effingham-school', 80, -580],
    ['effingham-gas-station', 420, -480],
    ['effingham-farm-store', -450, -480],
    ['effingham-car-dealer', 5100, -540],
    ['effingham-motel', 5350, -520],
  ];
  for (const [b, x, y] of places) {
    const z = EF_SITE[b]; if (!z) continue;
    const sx0 = x - z.ux, sy0 = y - z.uy;
    out.push([sx0 - 4, sy0 - 4, sx0 + z.w + 4, sy0 + z.d + 4]);
  }
  // downtown courthouse / church pads (trimmed to building+parking)
  out.push([2600 - 74, -500 - 17.5 - 114, 2600 + 74, -500 - 17.5]);
  out.push([2255 - 39, -500 - 17.5 - 99, 2255 + 39, -500 - 17.5]);
  return out;
}
function efOverlapsCivic(x0, y0, w, d) {
  const x1 = x0 + w, y1 = y0 + d;
  for (const [a, b, c, e] of efCivicRects()) {
    if (x0 < c && x1 > a && y0 < e && y1 > b) return true;
  }
  return false;
}

function drawEFIndustryFill() {
  // Busy industrial belt: reserve N–S corridors, register roof plans with uprights (Danny #6–10,13)
  const half = 14;
  const STREET = 250; // single industrial spine (reconcile old STREET_Y=252 band — Danny #11)
  const indNS = [3100, 3460, 3880, 4400, 4960, 5360, 5680];
  const indSkipX = indNS.map(x => [x - half - 2.5, x + half + 2.5]);
  fillRoadH(2960, 5750, STREET, half, true, indSkipX);
  // Solid industrial apron north of spine — kills grass show-through under plant pads (Danny final #1)
  // Ground PNGs themselves are pale greenish; apron + solid fillPad are the full-strength fix.
  g.fillStyle = '#8a8680';
  g.fillRect(sx(2960), sy(70), (5750 - 2960) * cam.z, (STREET - 10 - 70) * cam.z * K);
  const BELT = 470;
  fillRoadH(5200, 5750, BELT, half, true, [[5360 - half - 2.5, 5360 + half + 2.5], [5680 - half - 2.5, 5680 + half + 2.5]]);
  for (const x of indNS) {
    const y1 = (x >= 5200) ? 470 : (x >= 4300 ? 380 : 340); // east to belt; stop clear of glass pad
    fillRoadV(120, y1, x, half, true, [[STREET - half, STREET + half]].concat(x >= 5200 ? [[BELT - half, BELT + half]] : []));
    fillIntersection(x, STREET, half);
    paintCrosswalkV(x, STREET, half);
    paintCrosswalkH(x, STREET, half);
    if (x >= 5200) {
      fillIntersection(x, BELT, half);
      paintCrosswalkV(x, BELT, half);
      paintCrosswalkH(x, BELT, half);
    }
  }

  function nearNS(x, w) {
    return indNS.some(ns => x - w / 2 < ns + half + 4 && x + w / 2 > ns - half - 4);
  }

  // Primary plants — upright centre + matching ground registered to near-wall base (Danny #6)
  const plants = [
    ['effingham-prairie-tool-factory@2x', 'effingham-prairie-tool-ground@2x', 3000, 155, 140, 90, 90, 44],
    ['effingham-wabash-electric@2x', 'effingham-wabash-ground@2x', 3160, 175, 100, 70, 70, 30],
    ['effingham-paper-warehouse@2x', 'effingham-paper-ground@2x', 3320, 150, 140, 95, 100, 40],
    ['effingham-prairie-tool-factory@2x', 'effingham-prairie-tool-ground@2x', 3500, 180, 140, 90, 90, 44],
    ['effingham-oak-street-lumber@2x', 'effingham-oak-street-ground@2x', 3680, 145, 140, 90, 100, 40],
    ['effingham-wabash-electric@2x', 'effingham-wabash-ground@2x', 3840, 170, 100, 70, 70, 30],
    ['effingham-paper-warehouse@2x', 'effingham-paper-ground@2x', 4000, 155, 140, 95, 100, 40],
    ['effingham-county-line-oil@2x', 'effingham-oil-ground@2x', 4180, 160, 140, 100, 100, 45],
    ['effingham-prairie-state-terminal@2x', null, 4420, 145, 180, 110, 160, 45],
    ['effingham-oak-street-lumber@2x', 'effingham-oak-street-ground@2x', 4680, 165, 140, 90, 100, 40],
    ['effingham-prairie-tool-factory@2x', 'effingham-prairie-tool-ground@2x', 4860, 150, 140, 90, 90, 44],
    ['effingham-paper-warehouse@2x', 'effingham-paper-ground@2x', 5060, 175, 140, 95, 100, 40],
    ['effingham-county-line-oil@2x', 'effingham-oil-ground@2x', 5240, 155, 140, 100, 100, 45],
    ['effingham-wabash-electric@2x', 'effingham-wabash-ground@2x', 5400, 170, 100, 70, 70, 30],
    ['effingham-prairie-state-terminal@2x', null, 5580, 145, 170, 100, 150, 45],
  ];
  plants.forEach(([upright, ground, x, y, gw, gd, sw, sh], i) => {
    // Cause: ground PNGs are opaque but pale greenish (lum~130–150) and read washed vs Burgess
    // solid #8a8680. Never draw those grounds — solid concrete only (Danny final #1).
    if (nearNS(x, gw * 0.5)) return; // only skip if centre sits on N–S
    const gx0 = x - gw / 2, gy0 = y - gd + 8;
    let useGd = gd;
    if (gy0 + gd > STREET - 8) useGd = Math.max(12, STREET - 8 - gy0);
    // Clip pad off N–S corridors rather than skipping the whole plant
    let px0 = gx0, pw = gw;
    for (const ns of indNS) {
      const L = ns - half - 3, R = ns + half + 3;
      if (px0 < R && px0 + pw > L) {
        // keep the larger remnant
        const leftW = Math.max(0, L - px0), rightW = Math.max(0, px0 + pw - R);
        if (leftW >= rightW && leftW >= 40) { pw = leftW; }
        else if (rightW >= 40) { px0 = R; pw = rightW; }
        else { pw = 0; }
      }
    }
    if (pw < 40) return;
    fillPad(px0, gy0, pw, useGd, '#8a8680'); // full-strength like Burgess
    drawEFSprite([upright, upright.replace('@2x', '')], x, y + 6, sw, sh);
    const driveX = x + (i % 2 ? 30 : -30);
    const driveY0 = Math.min(y + 20, STREET - 2);
    // Stephen fix2 #9: no stub drives — lots touch the spine; cars pull in directly

    // Trucks/cars only on the opaque pad
    const truckY = Math.min(y + 24, gy0 + useGd - 8);
    if (truckY > gy0 + 4 && truckY < STREET - 10) {
      drawEFTruck(x + 40, truckY, i);
      drawEFTruck(x - 45, Math.min(y + 28, gy0 + useGd - 6), i + 2);
      if (i % 2 === 0) drawEFTruck(x + 5, Math.min(y + 40, gy0 + useGd - 4), i + 4);
    }
    for (let j = 0; j < 4; j++) {
      if (j % 3 === 0) continue;
      const cx = gx0 + 12 + j * 18, cy = Math.min(y + 10, gy0 + useGd - 6);
      if (cx > gx0 + 4 && cx < gx0 + gw - 4 && cy > gy0 + 2 && cy < STREET - 10)
        drawEFParkedCar(cx, cy, j + i);
    }
    const fence = 'effingham-fence-industrial-chainlink-24ft@2x';
    for (let fx = gx0; fx < gx0 + gw - 12; fx += 24) {
      drawEFSprite([fence], fx + 12, gy0 + 3, 24, 10);
      drawEFSprite([fence], fx + 12, Math.min(gy0 + useGd - 3, STREET - 10), 24, 10);
    }
  });

  // Secondary fillers — each gets an opaque pad; drop if pad would clip away (Danny #4)
  const fillers = [
    [3080, 200, 70, 48], [3240, 195, 65, 45], [3400, 205, 72, 50], [3620, 198, 64, 44],
    [3780, 202, 68, 46], [3940, 195, 66, 45], [4120, 205, 70, 48], [4300, 198, 64, 44],
    [4560, 200, 80, 52], [4780, 195, 68, 46], [4980, 205, 72, 50], [5180, 198, 66, 45],
    [5340, 202, 68, 46], [5500, 195, 64, 44],
  ];
  const fillerArt = [
    'effingham-paper-warehouse@2x', 'effingham-wabash-electric@2x', 'effingham-prairie-tool-factory@2x',
    'effingham-oak-street-lumber@2x', 'effingham-paper-warehouse@2x'
  ];
  fillers.forEach(([x, y, w, d], i) => {
    if (nearNS(x, w)) return;
    const top = y - d / 2, bot = Math.min(y + d / 2, STREET - 10);
    if (bot - top < 28) return; // drop thin / bare-grass leftovers
    fillPad(x - w / 2, top, w, bot - top, '#6a6860');
    drawEFSprite([fillerArt[i % fillerArt.length]], x, Math.min(y, bot - 18), Math.min(70, w - 8), Math.min(32, bot - top - 6));
    if (i % 2 === 0) drawEFTruck(x + w / 3, Math.min(y + d / 3, bot - 10), i);
    if (i % 3 !== 0) drawEFParkedCar(x - w / 3, Math.min(y + d / 4, bot - 8), i);
    // no stub to spine (#9)

  });

  // South-of-street pad helper — do NOT use north clipPad (Danny #7 / Stephen Burgess)
  function fillPadSouth(x0, y0, w, d, col) {
    // y0 is top of pad; pad extends south (increasing y) away from STREET
    if (y0 < STREET + 6) y0 = STREET + 6; // keep clear of street+curb
    fillPad(x0, y0, w, d, col);
    return y0;
  }

  // Burgess — Danny embedded pad (rails baked in). No solid fillPad over tracks.
  // Lot apron flush with pad (same concrete) so pad is not a pasted rectangle (Stephen C).
  {
    const P = globalThis.EF_BURGESS_PAD || { x0: 3903.095, y0: 342, w: 372, d: 49.5 };
    const bx = P.x0 + P.w / 2, by = P.y0 - 8;
    const lotCol = '#9a9690'; // match embedded pad concrete
    // Keep STREET as the real road; no continuous grey strip street→pad (Danny quick #3)
    const lotX0 = P.x0 - 12, lotW = P.w + 24;
    // Pad-flush apron only (building/loading) — grass between STREET and pad
    fillPad(lotX0, P.y0 - 4, lotW, P.d + 12, lotCol);
    // Tiny pads under parked trucks only (not a strip)
    fillPad(bx - 100, STREET + 6, 48, 26, lotCol);
    fillPad(bx + 40, STREET + 6, 48, 26, lotCol);
    drawEFTruck(bx - 80, STREET + 18, 1); drawEFTruck(bx + 60, STREET + 16, 3);
    for (let j = 0; j < 4; j++) {
      if (j % 3 === 0) continue;
      drawEFParkedCar(bx - 90 + j * 40, STREET + 24, j);
    }
    globalThis.EF_BURGESS_BLDG = { bx, by };
  }

  // Scrapyard — full-gate open/closed (missing effingham-scrapyard@2x) + building on pad (Danny #13)
  {
    const bx = 3520, by = 1000;
    const padX = bx - 70, padY = by - 40, padW = 150, padD = 100;
    fillPad(padX, padY, padW, padD, '#5c5a52');
    // building / office on pad
    drawEFSprite(['effingham-paper-warehouse@2x'], bx - 30, by - 10, 55, 28);
    drawEFSprite(['effingham-scrapyard-full-gate-open@2x', 'effingham-scrapyard-gate-open@2x', 'effingham-scrapyard-gate-closed@2x'], bx + 20, by + 20, 48, 22);
    drawEFSprite(['effingham-scrapyard-crane@2x', 'effingham-scrapyard-crane-body@2x'], bx + 40, by - 5, 36, 40);
    // access from industrial spine south to scrap (contiguous)
    /* stub removed Stephen #9 */
    drawEFTruck(bx + 50, by - 20, 2);
  }

  // Midstate Glass — frame left (5210,534) 480×182 on pad (5200,490) 500×70 (Danny #10)
  {
    const padX = 5200, padY = 490, padW = 500, padD = 70;
    fillPad(padX, padY, padW, padD, '#6e6c64');
    const frameLeft = 5210, by = 534, fw = 480, fh = 182;
    const bx = frameLeft + fw / 2; // centre for drawEFSprite
    drawEFSprite(['effingham-glass@2x'], bx, by, fw, fh);
    // Contiguous drives from STREET south to pad (Danny #8)
    /* stub removed Stephen #9 */
    /* stub removed Stephen #9 */
    drawEFTruck(bx - 180, 548, 1); drawEFTruck(bx - 40, 550, 5);
    drawEFTruck(bx + 80, 548, 2); drawEFTruck(bx + 200, 546, 3);
  }

  // Illini Grain — building NORTH of parallel load/RA (y=-80/-94); nothing crosses bins (Stephen #7)
  {
    const imgLeft = 921.918, by = -118, fw = 640, fh = 168; // base north of GRA so upright clears tracks
    const bx = imgLeft + fw / 2; // = 1241.918 centre / spout x
    fillPad(911.918, -170, 660, 90, '#7a7870'); // lot behind (north of) the tracks
    drawEFSprite(['effingham-elevator@2x'], bx, by, fw, fh);
    drawEFTruck(bx - 280, -150, 2); drawEFTruck(bx + 260, -148, 4);
  }
  // Team ramp stub removed (Danny quick #2 — orphan grey south of main / between tracks)
  // Duplicate terminal/warehouse/trucks at (4880,280) REMOVED (Danny #7)
  // Keep one south-of-street secondary terminal east of Burgess, clear of N–S
  {
    const x0 = 4280, y0 = STREET + 10;
    fillPadSouth(x0, y0, 160, 95, '#6a6860');
    drawEFSprite(['effingham-prairie-state-terminal@2x'], x0 + 80, y0 + 50, 120, 38);
    drawEFSprite(['effingham-wabash-electric@2x'], x0 + 40, y0 + 78, 60, 28);
    for (let i = 0; i < 5; i++) {
      const tx = x0 + 15 + (i % 3) * 48, ty = y0 + 10 + Math.floor(i / 3) * 30;
      if (tx > x0 + 4 && tx < x0 + 156) drawEFTruck(tx, ty, i + 2);
    }
    /* stub removed Stephen #9 */
  }
  // Propane access fixed in drawFuelGround (Danny #8)
}

function drawEFHouses() {
  if (!EF_LOTS.length) return;
  // Danny final #2: fill every street front with 50–75 ft lots, both sides where room
  const PC = NWX, CLEAR = 25;
  const halfR = 14;
  const CURB = 17.5;
  const LOTS50 = EF_LOTS.filter(l => l.w >= 50 && l.w <= 60);
  const LOTS75 = EF_LOTS.filter(l => l.w > 60 && l.w <= 75);
  // Prefer 50–60 ft fronts (busy town); mix in some 75s
  let pool = LOTS50.length ? LOTS50.concat(LOTS50).concat(LOTS75) : EF_LOTS.filter(l => l.w >= 50 && l.w <= 75);
  if (!pool.length) pool = EF_LOTS.slice();
  const blocks = [
    // 280 ft street spacing → room for 120-ft lots on BOTH sides (Danny final #2)
    { streetY: -700, x0: 2050, x1: 3180 },
    { streetY: -840, x0: 2050, x1: 3180 },
    { streetY: -1120, x0: 2080, x1: 3100 },
    { streetY: -700, x0: 3200, x1: 3500 },
    { streetY: -700, x0: 4260, x1: 4680 },
    { streetY: -840, x0: 3200, x1: 3500 },
    { streetY: -840, x0: 4260, x1: 4600 },
    { streetY: -1120, x0: 3200, x1: 3500 },
    { streetY: -1120, x0: 4260, x1: 4550 },
    { streetY: -360, x0: 3320, x1: 3500 },
    { streetY: -360, x0: 4260, x1: 4680 },
    { streetY: -360, x0: -900, x1: 600 },
    { streetY: -640, x0: -800, x1: 500 },
    { streetY: -920, x0: -700, x1: 400 },
    { streetY: -1200, x0: -600, x1: 300 },
    { streetY: -360, x0: 4800, x1: 6200 },
    { streetY: -640, x0: 4900, x1: 6300 },
    { streetY: -920, x0: 5000, x1: 6100 },
    { streetY: -1200, x0: 5100, x1: 6000 },
  ];
  // Other street Ys on same corridor — used to test south-side clearance
  const streetYsByBand = {};
  for (const b of blocks) {
    const key = (b.x0 < 1000) ? 'W' : (b.x0 < 3600 ? 'D' : (b.x0 < 4700 ? 'M' : 'E'));
    (streetYsByBand[key] || (streetYsByBand[key] = [])).push(b.streetY);
  }
  for (const k of Object.keys(streetYsByBand)) streetYsByBand[k] = [...new Set(streetYsByBand[k])].sort((a,b)=>b-a);

  const nsReserve = [2180, 2460, 2740, 3020, 3100, 3460, 3880, 4400, 4960, 5360, 5680];
  let li = 0;

  function bandKey(x0) { return (x0 < 1000) ? 'W' : (x0 < 3600 ? 'D' : (x0 < 4700 ? 'M' : 'E')); }

  function packSide(b, allNS, side) {
    if (side > 0) {
      const ys = (streetYsByBand[bandKey(b.x0)] || []).concat([-500, -360, -210, -70]);
      const nextSouth = ys.filter(y => y > b.streetY + 1).sort((a,c)=>a-c)[0];
      const limit = (nextSouth != null ? nextSouth : -70) - CURB;
      // Need full lot depth + margin; only pack south when streets are wide enough
      if (b.streetY + CURB + 120 + 8 > limit) return;
    }
    let x = b.x0;
    let guard = 0;
    while (x < b.x1 - 40 && guard++ < 120) {
      const lot = pool[li % pool.length]; li++;
      if (x < PC + CLEAR && x + lot.w > PC - CLEAR) { x = PC + CLEAR; continue; }
      let hitNS = false;
      for (const ns of allNS) {
        if (x < ns + halfR + 4 && x + lot.w > ns - halfR - 4) { x = ns + halfR + 5; hitNS = true; break; }
      }
      if (hitNS) continue;
      if (x + lot.w > b.x1 + 8) break;
      const y0 = side < 0 ? b.streetY - CURB - lot.d : b.streetY + CURB;
      if (x < 4260 && x + lot.w > 3500 && y0 < 40) { x = 4260; continue; }
      if (typeof efOverlapsCivic === 'function' && efOverlapsCivic(x, y0, lot.w, lot.d)) { x += Math.max(10, lot.w >> 2); continue; }
      if (y0 < 25 && y0 + lot.d > -25) { x += lot.w; continue; }
      drawEFLotAt(lot, x, b.streetY, li, side);
      if (li % 6 === 0) drawEFSprite(['effingham-streetlight-cobra@2x'], x + lot.w / 2, b.streetY + side * 4, 14, 30);
      x += lot.w + 2;
    }
  }

  // Pass 1: roads + collect every N–S corridor
  const globalNS = nsReserve.slice();
  for (const b of blocks) {
    const gaps = [[PC - 40, PC + 40]];
    if (b.x0 < 4260 && b.x1 > 3500 && b.streetY < 40) gaps.push([3500, 4260]);
    else if (b.x0 < 3880 && b.x1 > 3880) gaps.push([3880 - 50, 3880 + 50]);
    if (typeof efCivicRects === 'function') {
      for (const [a, , c, ] of efCivicRects()) {
        if (c > b.x0 - 40 && a < b.x1 + 40) gaps.push([a - 4, c + 4]);
      }
    }
    if (b.streetY > -100 && b.streetY < 50) gaps.push([2500, 3400]);
    for (const ns of nsReserve) {
      if (ns > b.x0 - 40 && ns < b.x1 + 40) gaps.push([ns - halfR - 3, ns + halfR + 3]);
    }
    // county road corridor on west blocks
    if (b.x0 < 500) gaps.push([380 - halfR - 3, 380 + halfR + 3]);
    fillRoadH(b.x0 - 20, b.x1 + 20, b.streetY, halfR, true, gaps);

  }
  // Stephen fix2 #8: one straight continuous N–S per x (no jogs/stubs). Fixed grid per band.
  const NS_DT = [2180, 2460, 2740, 3020];
  const NS_W = [-520, -200, 120, 420];
  const NS_E = [5100, 5400, 5700];
  function addContinuousNS(xs, yTop, yBot, skipYs) {
    for (const x of xs) {
      if (Math.abs(x - PC) < 50) continue;
      if (x > 3500 && x < 4260) continue; // wye keep-out
      fillRoadV(yTop, yBot, x, halfR, true, skipYs);
      if (!globalNS.includes(x)) globalNS.push(x);
    }
  }
  const skipDT = [-1120, -840, -700, -500, -360, -210].map(y => [y - halfR, y + halfR]);
  addContinuousNS(NS_DT, -1200, -210, skipDT); // T at Main — no stubs south into grass (#3)
  // West/east N–S T into southern E–W (−360); only county road (380) crosses the tracks
  addContinuousNS(NS_W, -1280, -360, [-1200, -920, -700, -640, -360].map(y => [y - halfR, y + halfR]));
  addContinuousNS(NS_E, -1280, -360, [-1200, -920, -640, -360].map(y => [y - halfR, y + halfR]));
  for (const b of blocks) {
    for (const ns of globalNS) {
      if (ns >= b.x0 - 20 && ns <= b.x1 + 20) {
        fillIntersection(ns, b.streetY, halfR);
        paintCrosswalkV(ns, b.streetY, halfR);
        paintCrosswalkH(ns, b.streetY, halfR);
      }
    }
  }
  // Pass 2: pack houses
  for (const b of blocks) {
    const allNS = globalNS.slice();
    if (b.x0 < 500) allNS.push(380);
    packSide(b, allNS, -1);
    packSide(b, allNS, +1);
  }
  const fenceY0 = -900, fenceY1 = -300;
  for (let fy = fenceY0; fy < fenceY1; fy += 24) {
    drawEFSprite(['effingham-fence-farm-wood-24ft@2x'], PC - CLEAR - 12, fy, 24, 5.5);
    drawEFSprite(['effingham-fence-farm-wood-24ft@2x'], PC + CLEAR + 12, fy, 24, 5.5);
  }
}

function drawEFGradeCrossings() {
  // Late paint county road so overview always shows both sides + lot
  fillRoadV(-900, -8, 380, 14, true, [[-10, 10]]);
  fillRoadV(8, 100, 380, 14, true);
  fillPad(340, 100, 80, 70, '#8a8680');
  // Planks run PARALLEL to the rails, between & just outside them, across the road width (Stephen).
  // Only where a real through street crosses a single main or the PC — never over yard/wye/house.
  const half = 14;
  const ox = [-4.6, -2.35, 2.35, 4.6]; // between rails (±gauge) and just outside
  function planksAcrossNS(x, y) { // N–S rails × E–W road at y
    g.fillStyle = '#6b5a45';
    const pw = Math.max(1.6, 0.9 * cam.z);
    for (const o of ox)
      g.fillRect(sx(x + o) - pw / 2, sy(y - half + 1), pw, (half * 2 - 2) * cam.z * K);
  }
  function planksAcrossEW(x, y) { // E–W rails × N–S road at x
    g.fillStyle = '#6b5a45';
    const pw = Math.max(1.6, 0.9 * cam.z);
    for (const o of ox)
      g.fillRect(sx(x - half + 1), sy(y + o) - pw / 2, (half * 2 - 2) * cam.z, pw);
  }
  // PC × every E–W that crosses it: downtown + residential blocks (Danny quick #1)
  for (const y of [-210, -360, -500, -700, -840, -1120]) planksAcrossNS(NWX, y);
  // County road kept as a real both-sides crossing (lot south of main); no orphan downtown N–S crossings
  planksAcrossEW(380, 0);
}

function efInBurgessPad(x, y) {
  const P = globalThis.EF_BURGESS_PAD; if (!P) return false;
  // Tiny inset — approach ballast/ties meet the pad edge (Stephen C)
  return x >= P.x0 + 0.15 && x <= P.x0 + P.w - 0.15 && y >= P.y0 + 0.15 && y <= P.y0 + P.d - 0.15;
}
function drawEFBurgessPad() {
  // Danny embedded pad at CLs 18.0 / 31.5 from south; reinforce rail heads so they read at game zoom.
  const P = globalThis.EF_BURGESS_PAD; if (!P) return;
  const key = 'effingham-burgess-pad-embedded@2x';
  if (!groundImg(key, P.x0, P.y0, P.w, P.d)) fillPad(P.x0, P.y0, P.w, P.d, '#9a9690');
  // Exact CL rail heads (matches B1=360 / B2=373.5) — thin, on top of embedded art
  // Rail heads at exact world CLs (B1=360, B2=373.5) — match approach rails
  for (const y of [360.0, 373.5]) {
    for (const o of [-2.35, 2.35]) {
      g.strokeStyle = '#1a1919'; g.lineWidth = Math.max(1.8, 0.65 * cam.z); g.lineCap = 'butt';
      g.beginPath(); g.moveTo(sx(P.x0), sy(y + o)); g.lineTo(sx(P.x0 + P.w), sy(y + o)); g.stroke();
      g.strokeStyle = '#d0cec8'; g.lineWidth = Math.max(0.9, 0.28 * cam.z);
      g.beginPath(); g.moveTo(sx(P.x0), sy(y + o)); g.lineTo(sx(P.x0 + P.w), sy(y + o)); g.stroke();
    }
  }
  const B = globalThis.EF_BURGESS_BLDG || { bx: P.x0 + P.w / 2, by: P.y0 - 8 };
  drawEFSprite(['effingham-burgess-side-full@2x', 'effingham-burgess@2x'], B.bx, B.by, 160, 55);
  fillPad(B.bx - 70, P.y0 - 22, 50, 14, '#8a8680');
  fillPad(B.bx + 20, P.y0 - 20, 40, 12, '#8a8680');
}
